mapper.select:

where 1 = 1
and r.visitor_uid like concat('%', #{visitorUid}, '%')
and r.questionnaire_id = #{questionnaireId}
and r.profile_id = #{profileId}
and r.top_plant_id = #{topPlantId}
and r.source_terminal = #{sourceTerminal}
and r.recommend_time >= #{params.beginTime}
and r.recommend_time <= #{params.endTime}
order by r.recommend_time desc, r.record_id desc
